import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';

const Dashboard = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('orders');

  
  const orders = JSON.parse(localStorage.getItem('campusOrders') || '[]');
  const postedItems = JSON.parse(localStorage.getItem('campusPostedItems') || '[]');

  const handleLogout = () => {
    localStorage.removeItem('campusUser');
    navigate('/');
  };

  const handleDeletePosted = (itemId) => {
    const updated = postedItems.filter((p) => p.id !== itemId);
    localStorage.setItem('campusPostedItems', JSON.stringify(updated));
    window.location.reload();
  };

  if (!currentUser) {
    return (
      <main className="page-shell" style={{ textAlign: 'center', padding: '80px 20px' }}>
        <div style={{ fontSize: '60px', marginBottom: '16px' }}>🔐</div>
        <h2 style={{ fontSize: '28px', fontWeight: '800', color: '#0f172a', marginBottom: '12px' }}>Please Login First</h2>
        <p style={{ color: '#64748b', marginBottom: '24px' }}>You need to be logged in to view your dashboard.</p>
        <button onClick={() => navigate('/')} style={{
          background: 'linear-gradient(135deg, #ec4899, #f43f5e)', color: 'white',
          border: 'none', padding: '14px 28px', borderRadius: '10px',
          fontWeight: '700', fontSize: '16px', cursor: 'pointer'
        }}>← Go to Home & Login</button>
      </main>
    );
  }

  return (
    <main className="page-shell" style={{ maxWidth: '900px', margin: '0 auto', padding: '32px 20px' }}>

      {/* Profile Header */}
      <div style={{
        background: 'linear-gradient(135deg, #667eea 0%, #ec4899 100%)',
        borderRadius: '20px', padding: '32px', marginBottom: '32px',
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        flexWrap: 'wrap', gap: '16px', color: 'white'
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
          <div style={{
            width: '72px', height: '72px', borderRadius: '50%',
            background: 'rgba(255,255,255,0.25)', display: 'flex',
            alignItems: 'center', justifyContent: 'center',
            fontSize: '32px', fontWeight: '800', border: '3px solid rgba(255,255,255,0.5)'
          }}>
            {currentUser.name?.charAt(0).toUpperCase()}
          </div>
          <div>
            <p style={{ fontSize: '13px', opacity: 0.8, margin: '0 0 4px' }}>Welcome back 👋</p>
            <h2 style={{ fontSize: '26px', fontWeight: '800', margin: '0 0 4px' }}>{currentUser.name}</h2>
            <p style={{ fontSize: '13px', opacity: 0.8, margin: 0 }}>✉️ {currentUser.email}</p>
          </div>
        </div>
        <div style={{ display: 'flex', gap: '16px', flexWrap: 'wrap' }}>
          <div style={{ background: 'rgba(255,255,255,0.2)', borderRadius: '12px', padding: '16px 24px', textAlign: 'center' }}>
            <p style={{ fontSize: '28px', fontWeight: '900', margin: 0 }}>{orders.length}</p>
            <p style={{ fontSize: '12px', opacity: 0.85, margin: 0 }}>Orders</p>
          </div>
          <div style={{ background: 'rgba(255,255,255,0.2)', borderRadius: '12px', padding: '16px 24px', textAlign: 'center' }}>
            <p style={{ fontSize: '28px', fontWeight: '900', margin: 0 }}>{postedItems.length}</p>
            <p style={{ fontSize: '12px', opacity: 0.85, margin: 0 }}>Listed Items</p>
          </div>
          <button onClick={handleLogout} style={{
            background: 'rgba(255,255,255,0.2)', color: 'white', border: '2px solid rgba(255,255,255,0.4)',
            padding: '12px 20px', borderRadius: '10px', cursor: 'pointer', fontWeight: '700', fontSize: '14px'
          }}>🚪 Logout</button>
        </div>
      </div>

      {/* Tabs */}
      <div style={{ display: 'flex', gap: '8px', marginBottom: '24px', background: '#f1f5f9', padding: '6px', borderRadius: '12px' }}>
        {[
          { key: 'orders', label: '📦 My Orders', count: orders.length },
          { key: 'posted', label: '🏷️ My Listings', count: postedItems.length },
        ].map((tab) => (
          <button key={tab.key} onClick={() => setActiveTab(tab.key)} style={{
            flex: 1, padding: '12px', border: 'none', borderRadius: '8px', cursor: 'pointer',
            fontWeight: '700', fontSize: '15px', transition: 'all 0.2s',
            background: activeTab === tab.key ? 'linear-gradient(135deg, #ec4899, #f43f5e)' : 'transparent',
            color: activeTab === tab.key ? 'white' : '#64748b',
            boxShadow: activeTab === tab.key ? '0 4px 12px rgba(236,72,153,0.3)' : 'none'
          }}>
            {tab.label} {tab.count > 0 && <span style={{
              background: activeTab === tab.key ? 'rgba(255,255,255,0.3)' : '#ec4899',
              color: 'white', borderRadius: '20px', padding: '2px 8px', fontSize: '12px', marginLeft: '6px'
            }}>{tab.count}</span>}
          </button>
        ))}
      </div>

      {/* Orders Tab */}
      {activeTab === 'orders' && (
        <div>
          {orders.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '60px 20px', background: '#f8fafc', borderRadius: '16px' }}>
              <div style={{ fontSize: '60px', marginBottom: '16px' }}>🛒</div>
              <h3 style={{ color: '#0f172a', fontSize: '20px', fontWeight: '700', marginBottom: '8px' }}>No orders yet</h3>
              <p style={{ color: '#64748b', marginBottom: '24px' }}>Browse items and place your first order!</p>
              <Link to="/browse" style={{
                background: 'linear-gradient(135deg, #ec4899, #f43f5e)', color: 'white',
                padding: '12px 24px', borderRadius: '10px', textDecoration: 'none', fontWeight: '700'
              }}>Browse Items</Link>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
              {[...orders].reverse().map((order) => (
                <div key={order.orderId} style={{
                  background: 'white', borderRadius: '14px', padding: '20px',
                  boxShadow: '0 4px 16px rgba(15,23,42,0.08)',
                  display: 'flex', gap: '16px', alignItems: 'center', flexWrap: 'wrap',
                  border: '1px solid #e2e8f0'
                }}>
                  <div style={{
                    width: '72px', height: '72px', borderRadius: '10px', flexShrink: 0,
                    backgroundImage: `url(${order.image})`, backgroundSize: 'cover', backgroundPosition: 'center'
                  }} />
                  <div style={{ flex: 1, minWidth: '180px' }}>
                    <h4 style={{ fontSize: '16px', fontWeight: '700', color: '#0f172a', margin: '0 0 4px' }}>{order.title}</h4>
                    <p style={{ fontSize: '13px', color: '#64748b', margin: '0 0 4px' }}>
                      Seller: {order.seller} • 📞 {order.sellerContact}
                    </p>
                    <p style={{ fontSize: '12px', color: '#94a3b8', margin: 0 }}>📅 {order.orderedAt}</p>
                  </div>
                  <div style={{ textAlign: 'right' }}>
                    <p style={{ fontSize: '22px', fontWeight: '800', color: '#ec4899', margin: '0 0 6px' }}>₹{order.price}</p>
                    <span style={{
                      background: '#d1fae5', color: '#065f46', padding: '4px 12px',
                      borderRadius: '20px', fontSize: '12px', fontWeight: '700'
                    }}>✅ Confirmed</span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Posted Items Tab */}
      {activeTab === 'posted' && (
        <div>
          {postedItems.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '60px 20px', background: '#f8fafc', borderRadius: '16px' }}>
              <div style={{ fontSize: '60px', marginBottom: '16px' }}>🏷️</div>
              <h3 style={{ color: '#0f172a', fontSize: '20px', fontWeight: '700', marginBottom: '8px' }}>No listings yet</h3>
              <p style={{ color: '#64748b', marginBottom: '24px' }}>Post your first item and reach campus buyers!</p>
              <Link to="/add-product" style={{
                background: 'linear-gradient(135deg, #ec4899, #f43f5e)', color: 'white',
                padding: '12px 24px', borderRadius: '10px', textDecoration: 'none', fontWeight: '700'
              }}>+ Post Item</Link>
            </div>
          ) : (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(240px, 1fr))', gap: '16px' }}>
              {postedItems.map((item) => (
                <div key={item.id} style={{
                  background: 'white', borderRadius: '14px', overflow: 'hidden',
                  boxShadow: '0 4px 16px rgba(15,23,42,0.08)', border: '1px solid #e2e8f0'
                }}>
                  <div style={{
                    height: '140px', backgroundImage: `url(${item.image || 'https://via.placeholder.com/300'})`,
                    backgroundSize: 'cover', backgroundPosition: 'center', position: 'relative'
                  }}>
                    <span style={{
                      position: 'absolute', top: '8px', left: '8px',
                      background: '#ec4899', color: 'white', padding: '4px 10px',
                      borderRadius: '20px', fontSize: '11px', fontWeight: '700'
                    }}>{item.category}</span>
                  </div>
                  <div style={{ padding: '16px' }}>
                    <h4 style={{ fontSize: '15px', fontWeight: '700', color: '#0f172a', margin: '0 0 6px' }}>{item.title}</h4>
                    <p style={{ fontSize: '18px', fontWeight: '800', color: '#ec4899', margin: '0 0 12px' }}>₹{item.price}</p>
                    <div style={{ display: 'flex', gap: '8px' }}>
                      <Link to={`/product/${item.id}`} style={{
                        flex: 1, background: '#f1f5f9', color: '#0f172a', padding: '8px',
                        borderRadius: '8px', textDecoration: 'none', fontWeight: '600',
                        fontSize: '13px', textAlign: 'center'
                      }}>👁 View</Link>
                      <button onClick={() => handleDeletePosted(item.id)} style={{
                        flex: 1, background: '#fef2f2', color: '#dc2626', border: 'none',
                        padding: '8px', borderRadius: '8px', cursor: 'pointer',
                        fontWeight: '600', fontSize: '13px'
                      }}>🗑 Remove</button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </main>
  );
};

export default Dashboard;
